#!/usr/bin/env python3
#
# Install Windows on Snapdragon SDKs for llama.cpp.
#

import sys
import os
import argparse
import shutil
import logging
import json
import hashlib
import tarfile
import tempfile
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen

from sdk import SDK_CONFIGS, get_hexagon_tools_dir, is_valid_sdk


logger = logging.getLogger("setup_sdk")

DEFAULT_SDK_BASE_DIR = r"C:\Qualcomm"


def get_sdk_releases(config):
    request = Request(
        f"https://api.github.com/repos/{config['repo']}/releases?per_page=100",
        headers={"Accept": "application/vnd.github+json", "User-Agent": "llama.cpp"},
    )
    try:
        with urlopen(request, timeout=30) as response:
            releases = json.load(response)
    except (HTTPError, URLError, TimeoutError) as err:
        raise RuntimeError(f"Cannot query {config['name']} releases: {err}") from err

    result = []
    for release in releases:
        if release["draft"] or release["prerelease"]:
            continue
        version = release["tag_name"].removeprefix("v")
        archive_name = f"{config['archive_prefix']}{version}-arm64-wos.tar.xz"
        for asset in release["assets"]:
            if asset["name"] != archive_name:
                continue
            result.append({
                "version": version,
                "name": asset["name"],
                "url": asset["browser_download_url"],
                "sha256": (asset.get("digest") or "").removeprefix("sha256:"),
            })
    return result


def list_sdk_releases():
    for config in SDK_CONFIGS:
        logger.info("%s:", config["name"])
        releases = get_sdk_releases(config)
        if not releases:
            logger.info("  no Windows on Snapdragon releases found")
            continue
        for release in releases:
            logger.info("  %s: %s", release["version"], release["name"])


def get_sdk_release(config, version):
    version = version or config["default_version"]
    version = version.removeprefix("v")
    for release in get_sdk_releases(config):
        if release["version"] == version:
            if not release["sha256"]:
                raise RuntimeError(f"{config['name']} {version} does not provide a SHA-256 digest")
            return release
    raise RuntimeError(
        f"No Windows on Snapdragon release for {config['name']} {version}. "
        "Run scripts/snapdragon/setup-sdk.py --list-sdk-releases to see available versions."
    )


def sha256sum(path):
    digest = hashlib.sha256()
    with open(path, "rb") as file:
        for chunk in iter(lambda: file.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def download_sdk(release, archive):
    while True:
        if archive.exists() and sha256sum(archive) == release["sha256"]:
            logger.info("Using existing archive %s", archive)
            return

        offset = archive.stat().st_size if archive.exists() else 0
        headers = {"User-Agent": "llama.cpp"}
        if offset:
            headers["Range"] = f"bytes={offset}-"
            logger.info("Resuming download of %s at %d MiB", release["name"], offset // (1024 * 1024))
        else:
            logger.info("Downloading %s", release["name"])

        try:
            with urlopen(Request(release["url"], headers=headers), timeout=30) as response:
                mode = "ab" if offset and response.status == 206 else "wb"
                with open(archive, mode) as file:
                    shutil.copyfileobj(response, file)
        except HTTPError as err:
            if err.code != 416:
                raise RuntimeError(f"Cannot download {release['name']}: {err}") from err
            archive.unlink(missing_ok=True)
            continue
        except (URLError, TimeoutError) as err:
            raise RuntimeError(f"Cannot download {release['name']}: {err}") from err

        if sha256sum(archive) == release["sha256"]:
            return
        raise RuntimeError(f"SHA-256 mismatch for {archive}. Re-run the command to resume the download.")


def extract_sdk(config, archive, target_dir):
    if not hasattr(tarfile, "data_filter"):
        raise RuntimeError("SDK extraction requires Python 3.10.12 or later")

    with tempfile.TemporaryDirectory(prefix=f".{target_dir.name}.tmp-", dir=target_dir.parent) as staging_path:
        staging_dir = Path(staging_path)
        with tarfile.open(archive, "r:xz") as tar:
            tar.extractall(staging_dir, filter=tarfile.data_filter)

        candidates = [staging_dir] + [path for path in staging_dir.iterdir() if path.is_dir()]
        extracted_dirs = [path for path in candidates if is_valid_sdk(config, path)]
        if len(extracted_dirs) != 1:
            raise RuntimeError(f"{config['name']} archive does not contain the expected files")
        extracted_dir = extracted_dirs[0]

        backup_dir = None
        if target_dir.exists():
            backup_dir = target_dir.parent / f".{target_dir.name}.backup"
            if backup_dir.exists():
                raise RuntimeError(f"Cannot replace {target_dir}: backup directory {backup_dir} already exists")
            target_dir.replace(backup_dir)
        try:
            extracted_dir.replace(target_dir)
        except Exception:
            if backup_dir:
                backup_dir.replace(target_dir)
            raise
        if backup_dir:
            shutil.rmtree(backup_dir)


def install_sdk(config, version, base_dir, force):
    version = (version or config["default_version"]).removeprefix("v")
    target_dir = base_dir / config["parent_dir"] / version
    if is_valid_sdk(config, target_dir) and not force:
        logger.info("Using existing %s at %s", config["name"], target_dir)
        return target_dir

    release = get_sdk_release(config, version)
    target_dir.parent.mkdir(parents=True, exist_ok=True)
    archive = target_dir.parent / release["name"]
    download_sdk(release, archive)
    logger.info("Extracting %s to %s", config["name"], target_dir)
    extract_sdk(config, archive, target_dir)
    archive.unlink(missing_ok=True)
    return target_dir


def set_user_environment(values):
    if os.name != "nt":
        raise RuntimeError("SDK setup must run on Windows")

    import winreg

    with winreg.CreateKey(winreg.HKEY_CURRENT_USER, "Environment") as key:
        for name, value in values.items():
            winreg.SetValueEx(key, name, 0, winreg.REG_SZ, str(value))
            os.environ[name] = str(value)

    import ctypes

    result = ctypes.c_ulong()
    ctypes.windll.user32.SendMessageTimeoutW(0xffff, 0x001a, 0, "Environment", 0x0002, 5000, ctypes.byref(result))


def setup_sdks(args):
    base_dir = Path(args.sdk_base_dir).expanduser().resolve()
    hexagon_config, opencl_config = SDK_CONFIGS
    environment = {}

    if args.hexagon is not None:
        hexagon_dir = install_sdk(hexagon_config, args.hexagon, base_dir, args.force)
        environment["HEXAGON_SDK_ROOT"] = hexagon_dir
        environment["HEXAGON_TOOLS_ROOT"] = get_hexagon_tools_dir(hexagon_dir)
    if args.opencl is not None:
        opencl_dir = install_sdk(opencl_config, args.opencl, base_dir, args.force)
        environment["OPENCL_SDK_ROOT"] = opencl_dir

    set_user_environment(environment)
    logger.info("SDK environment variables were updated. Start a new terminal before building.")


def main():
    logging.basicConfig(level=logging.INFO, format="%(message)s")
    parser = argparse.ArgumentParser(description="Install Windows on Snapdragon SDKs for llama.cpp.")
    parser.add_argument("--list-sdk-releases", action="store_true", help="List available Windows on Snapdragon SDK releases")
    parser.add_argument("--sdk-base-dir", default=DEFAULT_SDK_BASE_DIR, help=r"SDK installation directory (default: C:\Qualcomm)")
    parser.add_argument("--hexagon", nargs="?", const=SDK_CONFIGS[0]["default_version"], metavar="VERSION", help="Install the Hexagon SDK, optionally selecting a version")
    parser.add_argument("--opencl", nargs="?", const=SDK_CONFIGS[1]["default_version"], metavar="VERSION", help="Install the OpenCL SDK, optionally selecting a version")
    parser.add_argument("--force", action="store_true", help="Reinstall selected SDKs even when they already exist")
    args = parser.parse_args()

    if args.list_sdk_releases:
        if args.sdk_base_dir != DEFAULT_SDK_BASE_DIR or args.hexagon is not None or args.opencl is not None or args.force:
            parser.error("Installation options cannot be combined with --list-sdk-releases")
        list_sdk_releases()
        return
    if args.hexagon is None and args.opencl is None:
        parser.error("Select at least one SDK with --hexagon or --opencl")
    if os.name != "nt":
        parser.error("SDK setup must run on Windows")
    setup_sdks(args)


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        logger.info("\nInterrupted by user.")
        sys.exit(130)
    except RuntimeError as err:
        logger.error("Error: %s", err)
        sys.exit(1)

from __future__ import annotations

import json

from pathlib import Path
from typing import Any, Callable, Iterator, TYPE_CHECKING

if TYPE_CHECKING:
    from torch import Tensor

from .base import ModelBase, gguf, logger
from .qwen import Qwen3Model


def _is_vllm_decision2_checkpoint(dir_model: Path) -> bool:
    if not (dir_model / "config.json").is_file():
        return False
    with open(dir_model / "config.json", encoding="utf-8") as f:
        return json.load(f).get("decision_format") == "vllm-sr-decision"


@ModelBase.register_hparams_loader(_is_vllm_decision2_checkpoint)
def _load_vllm_decision2_hparams(dir_model: Path) -> dict[str, Any]:
    logger.info("gguf: detected vllm-sr Decision 2.0 checkpoint")
    with open(dir_model / "config.json", encoding="utf-8") as f:
        package = json.load(f)
    hparams = ModelBase.load_hparams((dir_model / package["backbone"]["config"]).parent, False, guess=False)
    hparams["architectures"] = ["VllmDecision2Model"]
    with open(dir_model / package["model_config"], encoding="utf-8") as f:
        hparams["decision"] = json.load(f)
    with open(dir_model / "score_bias.json", encoding="utf-8") as f:
        hparams["decision"]["score_bias"] = json.load(f)["offsets"]
    return hparams


@ModelBase.register("VllmDecision2Model")
@ModelBase.example("vllm-sr/Decision-2.0-Kai-0.6B")
class VllmDecision2Model(Qwen3Model):
    model_arch = gguf.MODEL_ARCH.VLLM_DECISION2

    # torch.nn.LayerNorm default, used by the head
    _HEAD_NORM_EPS = 1e-5

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        head = self.hparams["decision"]
        if head["architecture"] != "qwen3-text-endpoints-global-query-shared-bilinear-mlp" or head["head_variant"] != "shared":
            raise ValueError(f"unsupported decision head: {head['architecture']}")

    def index_tensors(self, *args, **kwargs) -> dict[str, Callable[[], Tensor]]:
        # the backbone weights are in their own directory
        dir_model, self.dir_model = self.dir_model, self.dir_model / "backbone"
        try:
            return super().index_tensors(*args, **kwargs)
        finally:
            self.dir_model = dir_model

    def get_tensors(self) -> Iterator[tuple[str, Tensor]]:
        yield from super().get_tensors()
        from safetensors.torch import load_file
        for name, data in load_file(self.dir_model / "decision_head.safetensors").items():
            yield "decision_head." + name, data

    def tensor_force_quant(self, name: str, new_name: str, bid: int | None, n_dims: int) -> gguf.GGMLQuantizationType | bool:
        # the head is computed in F32
        if new_name.startswith("decision."):
            return gguf.GGMLQuantizationType.F32
        return super().tensor_force_quant(name, new_name, bid, n_dims)

    def set_vocab(self):
        super().set_vocab()
        self.gguf_writer.add_chat_template([{"name": "systemone", "template": self._systemone_template()}])

    @classmethod
    def _systemone_template(cls) -> str:
        # prompt follows decision2/_vendor/dev2model/decision_model.py (segments) of the model repo
        # the pieces of the prompt are tokenized one by one, the server gives the text that separates them (sep)
        # and the text that starts the span of a question or of an option (mark_question, mark_option)
        # the head reads the last token of each option and the last token of the question
        # the start of an option is a piece of its own, so that the spans of two options are not joined
        # the keys of JSON objects are given in sorted order
        def text(value: str) -> str:
            return "{{ " + json.dumps(value) + " }}"

        def render(name: str) -> str:
            return "{{ " + name + " if " + name + " is string else " + name + " | tojson(separators=[',', ':']) }}"

        option = (
            "{% set d = o.description %}"
            "{% if q.type == 'noul' and d is none %}{% set d = 'Yes' if o.key == 'true' else 'No' %}{% endif %}"
            "{{ {'description': d, 'key': o.key} | tojson(separators=[',', ':']) }}"
        )
        return (
            "{% for q in questions %}"
            + text("Context:\n") + render("state")
            + text("\n\nTask type: ") + "{{ q.type }}" + text("\nQuestion:\n") + render("q.instructions") + text("\nOptions:")
            + "{% for o in q.options %}{{ sep }}" + text("\n<option>\n") + "{{ sep }}{{ mark_option }}" + option + text("\n</option>") + "{% endfor %}"
            + "{{ sep }}{{ mark_question }}" + text("\n\nSelect the single option best supported by the context and instructions.\nDecision:")
            + "{% endfor %}"
        )

    def set_gguf_parameters(self):
        super().set_gguf_parameters()
        self.gguf_writer.add_decision_type(gguf.DecisionType.VLLM_DECISION2)
        self.gguf_writer.add_layer_norm_eps(self._HEAD_NORM_EPS)
        for offsets in self.hparams["decision"]["score_bias"].values():
            self.gguf_writer.add_decision_score_bias(offsets)

import { Compass, Eye, EyeOff, Heart, HeartOff, Trash2 } from '@lucide/svelte';
import { MODEL_DOWNLOAD_ICONS } from '$lib/constants';
import { ModelRowDownloadState } from '$lib/enums';
import { modelsStore, uiStore } from '$lib/stores';
import type { ModelOption } from '$lib/types/models';
import { repoOf } from '$lib/utils';

export function modelRowActions(
	option: ModelOption,
	favorite: boolean,
	isHidden: boolean,
	onDelete: (option: ModelOption) => void,
	/** Download state, when the row stands for a tracked download. */
	download?: ModelRowDownloadState | null
) {
	const viewInDiscover = {
		icon: Compass,
		label: 'See in Discover',
		// the details pane is keyed by repo, not by `<repo>:<quant>`
		onclick: () => uiStore.openModelsDiscover(repoOf(option.model)),
		separator: true
	};

	// a tracked download is paused, resumed or dropped: it is not loaded, hidden or
	// drafted. An in-flight row cancels, which stops the download and removes the
	// partial files; a paused one deletes, which removes the partials from disk
	if (download) {
		const isPaused = download === ModelRowDownloadState.PAUSED;

		return [
			{
				icon: isPaused ? MODEL_DOWNLOAD_ICONS.resume : MODEL_DOWNLOAD_ICONS.pause,
				label: isPaused ? 'Resume downloading' : 'Pause downloading',
				onclick: () => void modelsStore.status.toggleDownload(option.model)
			},
			{
				icon: Trash2,
				label: isPaused ? 'Delete from disk' : 'Cancel download',
				onclick: () => onDelete(option),
				separator: true,
				variant: 'destructive' as const
			},
			viewInDiscover
		];
	}

	return [
		{
			icon: favorite ? HeartOff : Heart,
			label: favorite ? 'Remove from favorites' : 'Add to favorites',
			onclick: () => modelsStore.toggleFavorite(option.model)
		},
		{
			icon: Trash2,
			label: 'Delete from disk',
			onclick: () => onDelete(option),
			separator: true,
			variant: 'destructive' as const
		},
		{
			icon: isHidden ? Eye : EyeOff,
			label: isHidden ? 'Unhide model' : 'Hide model',
			onclick: () => modelsStore.toggleHidden(option.id),
			separator: true
		},
		viewInDiscover
	];
}

